<?php
class Solution {

    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $mod = 100000;
        $limit = 9999999999;

        $count2 = 0;
        $count5 = 0;
        $last = 1;
        $exact = 1;
        $logSum = 0.0;

        for ($i = $left; $i <= $right; $i++) {
            $logSum += log10($i);

            $x = $i;

            while ($x % 2 == 0) {
                $count2++;
                $x = intdiv($x, 2);
            }

            while ($x % 5 == 0) {
                $count5++;
                $x = intdiv($x, 5);
            }

            $last = ($last * ($x % $mod)) % $mod;

            if ($exact <= $limit) {
                if ($x != 0 && $exact <= intdiv($limit, $x)) {
                    $exact *= $x;
                } else {
                    $exact = $limit + 1;
                }
            }
        }

        $zeros = min($count2, $count5);
        $extraFactor = 1;
        $extraCount = 0;

        if ($count2 > $count5) {
            $extraFactor = 2;
            $extraCount = $count2 - $count5;
        } elseif ($count5 > $count2) {
            $extraFactor = 5;
            $extraCount = $count5 - $count2;
        }

        if ($extraCount > 0) {
            $last = ($last * $this->modPow($extraFactor, $extraCount, $mod)) % $mod;
        }

        if ($exact <= $limit) {
            for ($i = 0; $i < $extraCount; $i++) {
                if ($exact <= intdiv($limit, $extraFactor)) {
                    $exact *= $extraFactor;
                } else {
                    $exact = $limit + 1;
                    break;
                }
            }
        }

        if ($exact <= $limit) {
            return (string)$exact . "e" . (string)$zeros;
        }

        $frac = $logSum - floor($logSum);
        $leading = (int)floor(pow(10, $frac + 4));

        if ($leading >= 100000) {
            $leading = 99999;
        } elseif ($leading < 10000) {
            $leading = 10000;
        }

        $lastStr = str_pad((string)$last, 5, "0", STR_PAD_LEFT);

        return (string)$leading . "..." . $lastStr . "e" . (string)$zeros;
    }

    function modPow($base, $exp, $mod) {
        $result = 1;
        $base %= $mod;

        while ($exp > 0) {
            if ($exp % 2 == 1) {
                $result = ($result * $base) % $mod;
            }
            $base = ($base * $base) % $mod;
            $exp = intdiv($exp, 2);
        }

        return $result;
    }
}
