class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $digits = substr($s, 1, strlen($s) - 2);
        $n = strlen($digits);
        $ans = [];

        $possibleNumbers = function($str) {
            $len = strlen($str);
            $res = [];

            if ($len == 1) {
                $res[] = $str;
                return $res;
            }

            if ($str[0] != '0') {
                $res[] = $str;
            }

            for ($i = 1; $i < $len; $i++) {
                $left = substr($str, 0, $i);
                $right = substr($str, $i);

                if (strlen($left) > 1 && $left[0] == '0') {
                    continue;
                }

                if ($right[strlen($right) - 1] == '0') {
                    continue;
                }

                $res[] = $left . "." . $right;
            }

            return $res;
        };

        for ($i = 1; $i < $n; $i++) {
            $leftPart = substr($digits, 0, $i);
            $rightPart = substr($digits, $i);

            $leftNumbers = $possibleNumbers($leftPart);
            $rightNumbers = $possibleNumbers($rightPart);

            foreach ($leftNumbers as $left) {
                foreach ($rightNumbers as $right) {
                    $ans[] = "(" . $left . ", " . $right . ")";
                }
            }
        }

        return $ans;
    }
}
