    function checkStraightLine($coordinates) {
        $n = count($coordinates);
        if ($n <= 2) {
            return true;
        }

        $x0 = $coordinates[0][0];
        $y0 = $coordinates[0][1];
        $x1 = $coordinates[1][0];
        $y1 = $coordinates[1][1];

