    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function countMaxOrSubsets($nums) {
        $n = count($nums);
        $maxOr = 0;

        foreach ($nums as $num) {
            $maxOr |= $num;
        }

        $count = 0;
        $totalSubsets = 1 << $n;

        for ($mask = 1; $mask < $totalSubsets; $mask++) {
            $currentOr = 0;

            for ($i = 0; $i < $n; $i++) {
                if (($mask & (1 << $i)) != 0) {
                    $currentOr |= $nums[$i];
                }
            }

            if ($currentOr == $maxOr) {
                $count++;
            }
        }

        return $count;
    }
}
