class Solution {

    /**
     * @param TreeNode $root
     * @param Integer $x
     * @param Integer $y
     * @return Boolean
     */
    function isCousins($root, $x, $y) {
        $queue = [[$root, null]];
        $head = 0;

        while ($head < count($queue)) {
            $levelSize = count($queue) - $head;
            $parentX = null;
            $parentY = null;

            for ($i = 0; $i < $levelSize; $i++) {
                [$node, $parent] = $queue[$head++];

                if ($node->val === $x) {
                    $parentX = $parent;
                }

                if ($node->val === $y) {
                    $parentY = $parent;
                }

                if ($node->left !== null) {
                    $queue[] = [$node->left, $node->val];
                }

                if ($node->right !== null) {
                    $queue[] = [$node->right, $node->val];
                }
            }

            if ($parentX !== null || $parentY !== null) {
                return $parentX !== null && $parentY !== null && $parentX !== $parentY;
            }
        }

        return false;
    }
