class Solution {

    /**
     * @param String $word1
     * @param String $word2
     * @return Boolean
     */
    function closeStrings($word1, $word2) {
        $n1 = strlen($word1);
        $n2 = strlen($word2);

        if ($n1 !== $n2) {
            return false;
        }

        $freq1 = array_fill(0, 26, 0);
        $freq2 = array_fill(0, 26, 0);

        for ($i = 0; $i < $n1; $i++) {
            $freq1[ord($word1[$i]) - 97]++;
            $freq2[ord($word2[$i]) - 97]++;
        }

        for ($i = 0; $i < 26; $i++) {
            if (($freq1[$i] === 0) !== ($freq2[$i] === 0)) {
                return false;
            }
        }

        sort($freq1);
        sort($freq2);

        return $freq1 === $freq2;
    }
}
