class Solution {

    /**
     * @param String $s
     * @param String[][] $knowledge
     * @return String
     */
    function evaluate($s, $knowledge) {
        $dict = [];
        foreach ($knowledge as $pair) {
            $dict[$pair[0]] = $pair[1];
        }

        $n = strlen($s);
        $result = [];
        $i = 0;

        while ($i < $n) {
            if ($s[$i] === '(') {
                $j = $i + 1;
                while ($s[$j] !== ')') {
                    $j++;
                }

                $key = substr($s, $i + 1, $j - $i - 1);
                $result[] = isset($dict[$key]) ? $dict[$key] : "?";
                $i = $j + 1;
            } else {
                $j = $i;
                while ($j < $n && $s[$j] !== '(') {
                    $j++;
                }

                $result[] = substr($s, $i, $j - $i);
                $i = $j;
            }
        }

        return implode('', $result);
    }
}
