class Solution {

    /**
     * @param Integer[][] $graph
     * @return Integer[]
     */
    function eventualSafeNodes($graph) {
        $n = count($graph);
        $reverse = array_fill(0, $n, []);
        $outdegree = array_fill(0, $n, 0);

        for ($i = 0; $i < $n; $i++) {
            $outdegree[$i] = count($graph[$i]);
            foreach ($graph[$i] as $next) {
                $reverse[$next][] = $i;
            }
        }

        $queue = [];
        $head = 0;
        $safe = array_fill(0, $n, false);

        for ($i = 0; $i < $n; $i++) {
            if ($outdegree[$i] === 0) {
                $queue[] = $i;
            }
        }

        while ($head < count($queue)) {
            $node = $queue[$head++];
            $safe[$node] = true;

            foreach ($reverse[$node] as $prev) {
                $outdegree[$prev]--;
                if ($outdegree[$prev] === 0) {
                    $queue[] = $prev;
                }
            }
        }

        $result = [];
        for ($i = 0; $i < $n; $i++) {
            if ($safe[$i]) {
                $result[] = $i;
            }
        }

        return $result;
    }
}
