class MKAverage {
    private $m;
    private $k;
    private $maxVal = 100000;
    private $bitMask;
    private $countTree;
    private $sumTree;
    private $queue = [];
    private $head = 0;
    private $size = 0;
    private $totalSum = 0;

    /**
     * @param Integer $m
     * @param Integer $k
     */
    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->countTree = array_fill(0, $this->maxVal + 2, 0);
        $this->sumTree = array_fill(0, $this->maxVal + 2, 0);

        $this->bitMask = 1;
        while (($this->bitMask << 1) <= $this->maxVal) {
            $this->bitMask <<= 1;
        }
    }

    /**
     * @param Integer $num
     * @return NULL
     */
    function addElement($num) {
        $this->queue[] = $num;
        $this->size++;
        $this->totalSum += $num;
        $this->update($num, 1);

        if ($this->size > $this->m) {
            $old = $this->queue[$this->head];
            unset($this->queue[$this->head]);
            $this->head++;

            $this->size--;
            $this->totalSum -= $old;
            $this->update($old, -1);
        }
    }

    /**
     * @return Integer
     */
    function calculateMKAverage() {
        if ($this->size < $this->m) {
            return -1;
        }

        $smallestSum = $this->sumSmallest($this->k);
        $largestSum = $this->totalSum - $this->sumSmallest($this->m - $this->k);
        $middleSum = $this->totalSum - $smallestSum - $largestSum;

        return intdiv($middleSum, $this->m - 2 * $this->k);
    }

    private function update($val, $delta) {
        $sumDelta = $val * $delta;
        for ($i = $val; $i <= $this->maxVal; $i += ($i & -$i)) {
            $this->countTree[$i] += $delta;
            $this->sumTree[$i] += $sumDelta;
        }
    }

    private function prefixCount($idx) {
        $res = 0;
        while ($idx > 0) {
            $res += $this->countTree[$idx];
            $idx -= ($idx & -$idx);
        }
        return $res;
    }

    private function prefixSum($idx) {
        $res = 0;
        while ($idx > 0) {
            $res += $this->sumTree[$idx];
            $idx -= ($idx & -$idx);
        }
        return $res;
    }

    private function kth($k) {
        $idx = 0;
        for ($bit = $this->bitMask; $bit > 0; $bit >>= 1) {
            $next = $idx + $bit;
            if ($next <= $this->maxVal && $this->countTree[$next] < $k) {
                $idx = $next;
                $k -= $this->countTree[$next];
            }
        }
        return $idx + 1;
    }

    private function sumSmallest($cnt) {
        if ($cnt <= 0) {
            return 0;
        }

        $val = $this->kth($cnt);
        $lessCount = $this->prefixCount($val - 1);
        $lessSum = $this->prefixSum($val - 1);

        return $lessSum + ($cnt - $lessCount) * $val;
    }
}

