class Solution {

    /**
     * @param Integer[] $stones
     * @return Boolean
     */
    function canCross($stones) {
        $n = count($stones);

        if ($stones[1] != 1) {
            return false;
        }

        for ($i = 1; $i < $n; $i++) {
            if ($stones[$i] - $stones[$i - 1] > $i) {
                return false;
            }
        }

        $posToIndex = [];
        for ($i = 0; $i < $n; $i++) {
            $posToIndex[$stones[$i]] = $i;
        }

        $dp = array_fill(0, $n, []);
        $dp[0][0] = true;
        $lastIndex = $n - 1;

        for ($i = 0; $i < $n; $i++) {
            if (empty($dp[$i])) {
                continue;
            }

            foreach ($dp[$i] as $jump => $_) {
                $jump = (int)$jump;

                for ($nextJump = $jump - 1; $nextJump <= $jump + 1; $nextJump++) {
                    if ($nextJump <= 0) {
                        continue;
                    }

                    $nextPos = $stones[$i] + $nextJump;

                    if (isset($posToIndex[$nextPos])) {
                        $nextIndex = $posToIndex[$nextPos];

                        if ($nextIndex === $lastIndex) {
                            return true;
                        }

                        $dp[$nextIndex][$nextJump] = true;
                    }
                }
            }
        }

        return false;
    }
}
