class Solution {

    /**
     * @param Integer[][] $grid
     * @return Integer
     */
    function largestMagicSquare($grid) {
        $m = count($grid);
        $n = count($grid[0]);

        $row = [];
        for ($i = 0; $i < $m; $i++) {
            $row[$i] = array_fill(0, $n + 1, 0);
            for ($j = 0; $j < $n; $j++) {
                $row[$i][$j + 1] = $row[$i][$j] + $grid[$i][$j];
            }
        }

        $col = [];
        for ($i = 0; $i <= $m; $i++) {
            $col[$i] = array_fill(0, $n, 0);
        }
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $col[$i + 1][$j] = $col[$i][$j] + $grid[$i][$j];
            }
        }

        $diag = [];
        $anti = [];
        for ($i = 0; $i <= $m; $i++) {
            $diag[$i] = array_fill(0, $n + 1, 0);
            $anti[$i] = array_fill(0, $n + 1, 0);
        }

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $diag[$i + 1][$j + 1] = $diag[$i][$j] + $grid[$i][$j];
                $anti[$i + 1][$j] = $anti[$i][$j + 1] + $grid[$i][$j];
            }
        }

        $maxK = min($m, $n);

        for ($k = $maxK; $k >= 2; $k--) {
            for ($r = 0; $r + $k <= $m; $r++) {
                for ($c = 0; $c + $k <= $n; $c++) {
                    $target = $diag[$r + $k][$c + $k] - $diag[$r][$c];
                    $antiSum = $anti[$r + $k][$c] - $anti[$r][$c + $k];

                    if ($antiSum != $target) {
                        continue;
                    }

                    $ok = true;

                    for ($t = 0; $t < $k; $t++) {
                        $rowSum = $row[$r + $t][$c + $k] - $row[$r + $t][$c];
                        if ($rowSum != $target) {
                            $ok = false;
                            break;
                        }

                        $colSum = $col[$r + $k][$c + $t] - $col[$r][$c + $t];
                        if ($colSum != $target) {
                            $ok = false;
                            break;
                        }
                    }

                    if ($ok) {
                        return $k;
                    }
                }
            }
        }

        return 1;
    }
}
