    function maximumANDSum($nums, $numSlots) {
        $n = count($nums);

        $pow3 = array_fill(0, $numSlots + 1, 1);
        for ($i = 1; $i <= $numSlots; $i++) {
            $pow3[$i] = $pow3[$i - 1] * 3;
        }

        $memo = [];

        $dfs = function($idx, $state) use (&$dfs, &$memo, $nums, $numSlots, $n, $pow3) {
