            if (isset($memo[$state])) {
                return $memo[$state];
            }

            $best = 0;
            $num = $nums[$idx];

            for ($i = 0; $i < $numSlots; $i++) {
                $countInSlot = intdiv($state, $pow3[$i]) % 3;

                if ($countInSlot < 2) {
                    $slotNumber = $i + 1;
                    $newState = $state + $pow3[$i];
                    $value = ($num & $slotNumber) + $dfs($idx + 1, $newState);

                    if ($value > $best) {
                        $best = $value;
                    }
                }
            }

            $memo[$state] = $best;
            return $best;
        };

        return $dfs(0, 0);
    }
