        $complete = 0;

        foreach ($flowers as $f) {
            if ($f >= $target) {
                $complete++;
            } else {
                $incomplete[] = $f;
            }
        }

        sort($incomplete, SORT_NUMERIC);
        $m = count($incomplete);

        $prefix = array_fill(0, $m + 1, 0);
        for ($i = 0; $i < $m; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $incomplete[$i];
        }

        $ans = $complete * $full;

        for ($k = 0; $k <= $m; $k++) {
            $len = $m - $k;
            $costFull = $k * $target - ($prefix[$m] - $prefix[$len]);

            if ($costFull > $newFlowers) {
                break;
            }

            $remaining = $newFlowers - $costFull;
            $beauty = ($complete + $k) * $full;

            if ($len > 0) {
                $left = 1;
                $right = $len;
                $best = 1;

                while ($left <= $right) {
                    $mid = intdiv($left + $right, 2);
                    $need = $incomplete[$mid - 1] * $mid - $prefix[$mid];

                    if ($need <= $remaining) {
                        $best = $mid;
                        $left = $mid + 1;
                    } else {
                        $right = $mid - 1;
                    }
