class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function canPartitionKSubsets($nums, $k) {
        $n = count($nums);
        $sum = array_sum($nums);

        if ($sum % $k !== 0) {
            return false;
        }

        $target = intdiv($sum, $k);
        rsort($nums);

        if ($nums[0] > $target) {
            return false;
        }

        $fullMask = (1 << $n) - 1;
        $memo = [];

        $dfs = function($mask, $currentSum) use (&$dfs, &$memo, $nums, $n, $target, $fullMask) {
            if ($mask === $fullMask) {
                return true;
            }

            if (isset($memo[$mask])) {
                return $memo[$mask];
            }

            $prev = -1;

            for ($i = 0; $i < $n; $i++) {
                if (($mask & (1 << $i)) !== 0) {
                    continue;
                }

                if ($nums[$i] === $prev) {
                    continue;
                }

                if ($currentSum + $nums[$i] > $target) {
                    continue;
                }

                $nextMask = $mask | (1 << $i);
                $nextSum = ($currentSum + $nums[$i]) % $target;

                if ($dfs($nextMask, $nextSum)) {
                    $memo[$mask] = true;
                    return true;
                }

                $prev = $nums[$i];

                if ($currentSum === 0) {
                    break;
                }
            }

            $memo[$mask] = false;
            return false;
        };

        return $dfs(0, 0);
    }
}
