class Solution {

    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $len = count($slices);
        $pick = intdiv($len, 3);

        $case1 = array_slice($slices, 0, $len - 1);
        $case2 = array_slice($slices, 1);

        return max($this->solveLinear($case1, $pick), $this->solveLinear($case2, $pick));
    }

    private function solveLinear($arr, $k) {
        $m = count($arr);
        $neg = -1000000000000;

        $prev2 = array_fill(0, $k + 1, $neg);
        $prev1 = array_fill(0, $k + 1, $neg);

        $prev2[0] = 0;
        $prev1[0] = 0;

        for ($i = 1; $i <= $m; $i++) {
            $curr = array_fill(0, $k + 1, $neg);

            for ($j = 0; $j <= $k; $j++) {
                $best = $prev1[$j];

                if ($j > 0) {
                    $take = $prev2[$j - 1] + $arr[$i - 1];
                    if ($take > $best) {
                        $best = $take;
                    }
                }

                $curr[$j] = $best;
            }

            $prev2 = $prev1;
            $prev1 = $curr;
        }

        return $prev1[$k];
    }
}
