class Solution {

    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $size = $n * 3;

        $cells = array_fill(0, $size, array_fill(0, $size, false));

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $ch = $grid[$i][$j];
                $r = $i * 3;
                $c = $j * 3;

                if ($ch === '/') {
                    $cells[$r][$c + 2] = true;
                    $cells[$r + 1][$c + 1] = true;
                    $cells[$r + 2][$c] = true;
                } elseif ($ch === '\\') {
                    $cells[$r][$c] = true;
                    $cells[$r + 1][$c + 1] = true;
                    $cells[$r + 2][$c + 2] = true;
                }
            }
        }

        $regions = 0;
        $dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

        for ($i = 0; $i < $size; $i++) {
            for ($j = 0; $j < $size; $j++) {
                if (!$cells[$i][$j]) {
                    $regions++;

                    $queue = [$i * $size + $j];
                    $cells[$i][$j] = true;
                    $head = 0;

                    while ($head < count($queue)) {
                        $pos = $queue[$head++];
                        $x = intdiv($pos, $size);
                        $y = $pos % $size;

                        foreach ($dirs as $dir) {
                            $nx = $x + $dir[0];
                            $ny = $y + $dir[1];

                            if ($nx >= 0 && $nx < $size && $ny >= 0 && $ny < $size && !$cells[$nx][$ny]) {
                                $cells[$nx][$ny] = true;
                                $queue[] = $nx * $size + $ny;
                            }
                        }
                    }
                }
            }
        }

        return $regions;
    }
}
