            $baseBeforeF = 0;
            $baseBeforeS = 0;

            if ($m % 2 == 1) {
                $mid = intdiv($m + 1, 2);
                if ($mid < $f) {
                    $baseBeforeF++;
                }
                if ($mid < $s) {
                    $baseBeforeS++;
                }
            }

            $earliest = PHP_INT_MAX;
            $latest = 0;

            $enumerate = function($i, $beforeF, $beforeS) use (
                &$enumerate,
                &$dfs,
                &$earliest,
                &$latest,
                $m,
                $f,
                $s,
                $half,
                $nextM
            ) {
                if ($i > $half) {
                    $res = $dfs($nextM, $beforeF + 1, $beforeS + 1);
                    $earliest = min($earliest, $res[0] + 1);
                    $latest = max($latest, $res[1] + 1);
                    return;
                }

                $left = $i;
                $right = $m + 1 - $i;

                if ($left == $f || $right == $f) {
                    $winner = $f;
                    $enumerate(
                        $i + 1,
                        $beforeF + ($winner < $f ? 1 : 0),
                        $beforeS + ($winner < $s ? 1 : 0)
                    );
                } elseif ($left == $s || $right == $s) {
                    $winner = $s;
                    $enumerate(
                        $i + 1,
                        $beforeF + ($winner < $f ? 1 : 0),
                        $beforeS + ($winner < $s ? 1 : 0)
                    );
                } else {
                    $winner = $left;
                    $enumerate(
                        $i + 1,
                        $beforeF + ($winner < $f ? 1 : 0),
                        $beforeS + ($winner < $s ? 1 : 0)
                    );

                    $winner = $right;
                    $enumerate(
                        $i + 1,
                        $beforeF + ($winner < $f ? 1 : 0),
                        $beforeS + ($winner < $s ? 1 : 0)
                    );
                }
            };

            $enumerate(1, $baseBeforeF, $baseBeforeS);

            $memo[$key] = [$earliest, $latest];
            return $memo[$key];
        };

        return $dfs($n, $firstPlayer, $secondPlayer);
    }
