class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer[][] $edges
     * @return Integer[]
     */
    function getCoprimes($nums, $edges) {
        $n = count($nums);

        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $u = $e[0];
            $v = $e[1];
            $adj[$u][] = $v;
            $adj[$v][] = $u;
        }

        $coprime = array_fill(0, 51, []);
        for ($i = 1; $i <= 50; $i++) {
            for ($j = 1; $j <= 50; $j++) {
                $a = $i;
                $b = $j;
                while ($b != 0) {
                    $t = $a % $b;
                    $a = $b;
                    $b = $t;
                }
                if ($a == 1) {
                    $coprime[$i][] = $j;
                }
            }
        }

        $ans = array_fill(0, $n, -1);
        $lastDepth = array_fill(0, 51, -1);
        $lastNode = array_fill(0, 51, -1);

        $stackU = [];
        $stackP = [];
        $stackD = [];
        $stackState = [];
        $stackPrevD = [];
        $stackPrevN = [];

        $top = 0;
        $stackU[$top] = 0;
        $stackP[$top] = -1;
        $stackD[$top] = 0;
        $stackState[$top] = 0;
        $stackPrevD[$top] = -1;
        $stackPrevN[$top] = -1;
        $top++;

        while ($top > 0) {
            $top--;
            $u = $stackU[$top];
            $parent = $stackP[$top];
            $depth = $stackD[$top];
            $state = $stackState[$top];

            if ($state == 1) {
                $val = $nums[$u];
                $lastDepth[$val] = $stackPrevD[$top];
                $lastNode[$val] = $stackPrevN[$top];
                continue;
            }

            $val = $nums[$u];
            $bestDepth = -1;
            $bestNode = -1;

            foreach ($coprime[$val] as $cv) {
                if ($lastDepth[$cv] > $bestDepth) {
                    $bestDepth = $lastDepth[$cv];
                    $bestNode = $lastNode[$cv];
                }
            }

            $ans[$u] = $bestNode;

            $prevD = $lastDepth[$val];
            $prevN = $lastNode[$val];

            $lastDepth[$val] = $depth;
            $lastNode[$val] = $u;

            $stackU[$top] = $u;
            $stackP[$top] = $parent;
            $stackD[$top] = $depth;
            $stackState[$top] = 1;
            $stackPrevD[$top] = $prevD;
            $stackPrevN[$top] = $prevN;
            $top++;

            foreach ($adj[$u] as $v) {
                if ($v == $parent) {
                    continue;
                }
                $stackU[$top] = $v;
                $stackP[$top] = $u;
                $stackD[$top] = $depth + 1;
                $stackState[$top] = 0;
                $stackPrevD[$top] = -1;
                $stackPrevN[$top] = -1;
                $top++;
            }
        }

        return $ans;
    }
}
