class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $leftChild
     * @param Integer[] $rightChild
     * @return Boolean
     */
    function validateBinaryTreeNodes($n, $leftChild, $rightChild) {
        $indegree = array_fill(0, $n, 0);

        for ($i = 0; $i < $n; $i++) {
            $left = $leftChild[$i];
            if ($left != -1) {
                $indegree[$left]++;
                if ($indegree[$left] > 1) {
                    return false;
                }
            }

            $right = $rightChild[$i];
            if ($right != -1) {
                $indegree[$right]++;
                if ($indegree[$right] > 1) {
                    return false;
                }
            }
        }

        $root = -1;
        $rootCount = 0;

        for ($i = 0; $i < $n; $i++) {
            if ($indegree[$i] == 0) {
                $root = $i;
                $rootCount++;
            }
        }

        if ($rootCount != 1) {
            return false;
        }

        $visited = array_fill(0, $n, false);
        $stack = [$root];
        $count = 0;

        while (!empty($stack)) {
            $node = array_pop($stack);

            if ($visited[$node]) {
                return false;
            }

            $visited[$node] = true;
            $count++;

            if ($leftChild[$node] != -1) {
                $stack[] = $leftChild[$node];
            }

            if ($rightChild[$node] != -1) {
                $stack[] = $rightChild[$node];
            }
        }

        return $count == $n;
    }
}
