class Solution {

    /**
     * @param String[] $words
     * @param String $result
     * @return Boolean
     */
    function isSolvable($words, $result) {
        $n = count($words);

        for ($i = 0; $i < $n; $i++) {
            $words[$i] = trim($words[$i]);
        }
        $result = trim($result);

        $resLen = strlen($result);
        $maxWordLen = 0;
        $wordLens = [];

        $noZero = array_fill(0, 26, false);
        $seen = array_fill(0, 26, false);
        $uniqueCount = 0;

        for ($i = 0; $i < $n; $i++) {
            $len = strlen($words[$i]);
            $wordLens[$i] = $len;
            $maxWordLen = max($maxWordLen, $len);

            if ($len > 1) {
                $idx = ord($words[$i][0]) - 65;
                $noZero[$idx] = true;
            }

            for ($j = 0; $j < $len; $j++) {
                $idx = ord($words[$i][$j]) - 65;
                if (!$seen[$idx]) {
                    $seen[$idx] = true;
                    $uniqueCount++;
                }
            }
        }

        if ($resLen > 1) {
            $idx = ord($result[0]) - 65;
            $noZero[$idx] = true;
        }

        for ($i = 0; $i < $resLen; $i++) {
            $idx = ord($result[$i]) - 65;
            if (!$seen[$idx]) {
                $seen[$idx] = true;
                $uniqueCount++;
            }
        }

        if ($uniqueCount > 10) {
            return false;
        }

        if ($resLen < $maxWordLen || $resLen > $maxWordLen + 1) {
            return false;
        }

        $assign = array_fill(0, 26, -1);
        $used = array_fill(0, 10, false);

        $dfs = function($col, $row, $sum) use (&$dfs, &$words, &$wordLens, $n, $result, $resLen, &$assign, &$used, &$noZero) {
            if ($col == $resLen) {
                return $sum == 0;
            }

            if ($row < $n) {
                $len = $wordLens[$row];

                if ($col >= $len) {
                    return $dfs($col, $row + 1, $sum);
                }

                $charIdx = ord($words[$row][$len - 1 - $col]) - 65;

                if ($assign[$charIdx] != -1) {
                    return $dfs($col, $row + 1, $sum + $assign[$charIdx]);
                }

                for ($d = 0; $d <= 9; $d++) {
                    if ($used[$d]) {
                        continue;
                    }
                    if ($d == 0 && $noZero[$charIdx]) {
                        continue;
                    }

                    $assign[$charIdx] = $d;
                    $used[$d] = true;

                    if ($dfs($col, $row + 1, $sum + $d)) {
                        return true;
                    }

                    $assign[$charIdx] = -1;
                    $used[$d] = false;
                }

                return false;
            }

            $resultIdx = ord($result[$resLen - 1 - $col]) - 65;
            $digit = $sum % 10;
            $carry = intdiv($sum, 10);

            if ($assign[$resultIdx] != -1) {
                if ($assign[$resultIdx] != $digit) {
                    return false;
                }
                return $dfs($col + 1, 0, $carry);
            }

            if ($used[$digit]) {
                return false;
            }

            if ($digit == 0 && $noZero[$resultIdx]) {
                return false;
            }

            $assign[$resultIdx] = $digit;
            $used[$digit] = true;

            if ($dfs($col + 1, 0, $carry)) {
                return true;
            }

            $assign[$resultIdx] = -1;
            $used[$digit] = false;

            return false;
        };

        return $dfs(0, 0, 0);
    }
}
